quests[11404] = { id = 11404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruft den kopflosen Reiter", description = "Zahlreiche düstere Kerzen schmücken den Kürbisschrein, der höhnisch grinst...", sourceObjective = "Bringt eine düstere Kerze zur leicht aufgewühlten Erde.", progress = "Die Erde scheint erst vor kurzem aufgewühlt worden zu sein. Auf der obersten Schicht liegen Regenwürmer, die sich winden, um der finsteren Tiefe zu entkommen.", completion = "Werdet Ihr die Kerze niederlegen und den kopflosen Reiter aus seiner unseligen Ruhe erwecken?", sourceObjectiveStatus = "unverified-source-field" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für die Brauerei Drohn!", description = "Ihr wollt dem Braufest also zu Stärke und Ehre verhelfen. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nWir werden Euch einen Rennwidder für 4 Minuten borgen. Hier, nehmt auch diese Rennzügel.\n\nSeid aber vorsichtig. Diese geizigen Goblins haben entlang der Strecke keine Apfelkisten aufgestellt.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", completion = "Ihr habt Euer Wort gehalten und die Kunde von unseren Braumeistern verbreitet. Vielen Dank. Wir haben Euch diese Lose versprochen, hier habt Ihr sie. Ich kann mir gut vorstellen, dass die Trolle ihre Lose nicht so einfach rausrücken...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktschreier für T'chalis Voodoobrauerei!", description = "Wir müssen alle wissen lassen, dass die Trolle auf dem Braufest sind. Verbreitet die Kunde bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister. Ruft, was das Zeug hält!\n\nIch werde Euch das Ganze etwas erleichtern, indem ich Euch meinen Rennwidder für 4 Minuten borge. Hier, nehmt auch meine Rennzügel.\n\nSeid aber vorsichtig. Die Goblins haben entlang der Strecke keine Apfelkisten aufgestellt... sowas von geizig.", sourceObjective = "Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister.", completion = "Ihr habt's wirklich gemacht! Wir müssen uns gleich auf den Ansturm der Besucher vorbereiten, die sicher schon auf dem Weg sind! Danke!\n\nOh, richtig, wir hatten Euch eine Belohnung versprochen. Das dürfen wir natürlich nicht vergessen...\n\nIhr könnt uns gerne noch einmal helfen, kommt einfach an einem anderen Tag wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Widderrennen... zumindest fast", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", sourceObjective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", progress = "Kommt Ihr mit dem Reitwidder zurecht?", completion = "Hey, das war gar nicht schlecht... seid Ihr sicher, dass Ihr kein Zwerg seid?\n\nEs gibt noch viel mehr Rennen, nicht nur von meiner Seite. Ihr werdet auf dem gesamten Braufestplatz Leute finden, die nach einem ordentlichen Widderrennmeister suchen. Also dann, macht Euch selbst mal nützlich.\n\nOh! Nicht, dass Ihr's vergesst, diese Widder wurden auf legale Weise erworben. Nur damit wir uns verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin und zurück", description = "Ich bin froh, dass Ihr hier seid. Wir haben einiges um die Ohren! Der Goblin, der uns mehr Gebräu bringen sollte, hatte auf seinem Weg von Klingenhügel hierher einen Unfall. Ihr müsst uns das Gebräu zustellen!\n\nIch werde Euch auf einen meiner Rennwidder setzen und Ihr folgt einfach der Straße nach Klingenhügel.\n\nSobald Ihr nahe genug seid, wird man Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es einem meiner fähigen Assistenten zu. Wir brauchen drei Fässchen. Erledigt Eure Sache gut, dann haben wir eventuell weitere Aufträge für Euch.", sourceObjective = "Holt bei dem Goblin, der auf der Straße in der Nähe von Klingenhügel festsitzt, ein Fässchen ab und bringt es zu Widdermeister Rays Assistenten. Macht das Ganze dreimal, bevor Euer Widder verschwindet.", completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist, die Dunkeleisenzwerge immer wieder angreifen und unser Lieferant irgendwo feststeckt, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nHier sind die Marken, die wir Euch versprochen haben. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagte da jemand \"Souvenir\"?", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufestwidder", description = "Wenn Ihr Driz Purzelfix, dem Widderrennlehrling, diesen Stempel auf Eurer Hand zeigt, dann wird er Euch gestatten, einen Braufestwidder zu erwerben.", sourceObjective = "Bringt den Handstempel \"Ehrenbrauer\" zu Driz Purzelfix in der Nähe des Eingangs zum Braufestplatz in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt die wilden Wolpertinger!", description = "Hey, Ihr da. Ich bin ein verrückter Zwerg! Wir Zwerge glauben, dass man unsichtbare Kreaturen sehen kann, wenn man nur mit ausreichend Gebräu versorgt ist. Wahrscheinlich wandern sie genau in diesem Moment auf dem Braufestplatz umher! Ihr könnt sie aber nur sehen, wenn Ihr betrunken seid.\n\nWir Zwerge finden immer einen Grund, um zu trinken.\n\nIhr wollt doch bestimmt auch einen Grund haben, um zu trinken... Also, bringt mir fünf Wolpertinger mit Hilfe dieses Netzes, das ich von einem wirklich betrunkenen Zwerg habe.\n\nWenn Ihr sie nicht sehen könnt, seid Ihr wahrscheinlich nicht betrunken genug.", sourceObjective = "Der \"Zwerg\" Glodrak Jägerspatz möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr einen ordentlichen Rausch braucht, um die Biester sehen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Jetzt, da der kopflose Reiter in der Gegend ist, sind die mutigen Zwerge von Kharanos jederzeit für einen Einsatz der Brandwache bereit. Wollt auch Ihr helfen?\n\nDie Gebirgsjäger haben südlich von hier ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mit Hilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", completion = "Ihr seid ja pitschnass und mit Ruß verschmiert! Beim Feuerlöschen gewesen, nicht wahr?\n\nGut gemacht! Als ehrenamtliches Mitglied der Brandwache bitte ich Euch, wieder hierher zurückzukommen, falls unser Dorf Euch brauchen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung bei der Brandwache", description = "Solange der kopflose Reiter noch Angst und Schrecken verbreitet, sind die Friedensbewahrer jederzeit bereit für einen Einsatz der Brandwache. Wollt Ihr auch helfen?\n\nDie Friedensbewahrer haben westlich von hier, in Richtung der Exodar, ein kleines Lager für Übungen der Brandwache aufgestellt. Geht dorthin und löscht Feuer mit Hilfe von Wassereimern. Ihr könnt Eure Eimer hier beim Wasserfass füllen.\n\nBis dann, {name}. Besucht uns bitte wieder, wenn Ihr genug geübt habt!", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone.", sourceObjectiveStatus = "unverified-source-field" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest!", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Eisenschmiede, um ein kostenloses Bier zu erhalten.", sourceObjective = "Sprecht mit dem Organisator des Braufests.", completion = "Ho ho! Seid Ihr wegen des Freibiers hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Braufest!", completion = "Ho ho! Seid Ihr wegen des Freibiers hier?" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest!", description = "Sprecht mit dem Organisator des Braufests beim Braufestplatz außerhalb von Orgrimmar, um ein kostenloses Bier zu erhalten.", sourceObjective = "Sprecht mit dem Organisator des Braufests.", completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf dem Braufest!", completion = "Was?! Freibier? Ja, schon gut. Ich schätze, so etwas in der Art haben wir für dieses Jahr versprochen." }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Todespirscher haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Weitere Schäden an den Gebäuden von Brill können wir uns nicht leisten - also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nGeht Richtung Westen am Friedhof vorbei und folgt dem Straßenverlauf, bis Ihr das Übungslager erreicht.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Brill.", progress = "Habt Ihr ein paar Feuer gelöscht, {name}? Das Übungslager liegt westlich von Brill.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerübung", description = "Die Wachen haben ein Übungslager zum Feuerlöschen außerhalb der Stadt aufgebaut. Wir können nicht zulassen, dass der kopflose Reiter alles zunichte macht, was wir in harter Arbeit wieder aufgebaut haben - also erfüllt Eure Pflicht und übt Euch im Feuerlöschen!\n\nVerlasst die Stadt durch das südliche Tor in Richtung der Kreuzung. Dort werdet Ihr das Übungslager finden.", sourceObjective = "Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone beim Falkenplatz.", completion = "Gut gemacht, {name}! Kinder, seht Euch diesen Helden gut an. Nehmt Euch ein Beispiel an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicias Gedicht", description = "Hi! Ich habe für meine Freundin Caylee ein Gedicht verfasst. Sie verbringt Ihre Zeit gerne bei den Aldor in Shattrath. Ihr wisst schon, in der Scherbenwelt!\n\nWärt Ihr so freundlich und würdet ihr das Gedicht bringen? Meine Mutter sagt, ich sei noch zu jung, um selbst nach Shattrath zu reisen!", sourceObjective = "Man hat Euch gebeten, Alicias Gedicht zu Caylee Dak in Shattrath in der Scherbenwelt zu bringen.", progress = "Oh, ein Gedicht?", completion = "Was für ein anrührendes Gedicht. Habt vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet die Saboteure", description = "Die Angreifer der Dunkeleisenzwerge scheinen diesen Papierfetzen versehentlich zurückgelassen zu haben.\n\nObwohl die Pläne in einem verfremdeten zwergischen Dialekt verfasst worden sind, ist die Unterschrift \"Coren Düsterbräu\" eindeutig genug, genauso wie die Erwähnung der Taverne 'Zum Grimmigen Säufer', tief in den Schwarzfelstiefen. Ihr solltet den Überfällen ein Ende bereiten und den Organisator der Überfälle aufsuchen.", sourceObjective = "Sucht nach Coren Düsterbräu im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11481] = { id = 11481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krise am Sonnenbrunnen", description = "Bei den Naaru, ich danke Euch, {race}, für Euer Bemühen.\n\nUnsere Arbeit hier ist jedoch noch lange nicht beendet, weswegen ich Euch darum bitten muss, eine entscheidende Mission auszuführen - eine Mission so wichtig wie alle, mit denen ich Euch jemals beauftragt habe.\n\nUnsere Streitkräfte sind weit verteilt. Und um das Ganze noch schlimmer zu machen, mussten wir ein Kontingent nach Azeroth abbestellen, das die Entwicklung der Dinge auf dem Sonnenbrunnenplateau untersuchen soll.\n\nIhr werdet dort gebraucht, {name}. Meldet Euch bei Larethor und richtet ihm aus, ich wünschte, wir könnten mehr Männer entbehren.", sourceObjective = "Adyen der Lichtwächter auf der Aldorhöhe in Shattrath hat Euch gebeten, zum Sonnenbrunnenplateau zu reisen und dort mit Larethor zu sprechen.", completion = "Noch ein Soldat aus Shattrath? Welch willkommener Anblick!\n\nWünschte es gäbe mehr wie Euch, aber wir müssen mit dem auskommen, was uns gegeben ist. Was auch immer dort draußen geschieht, es wird nicht darauf warten, dass wir vorbereitet sind.\n\nSeht Euch ein wenig um, {class}. Es gibt viel zu erledigen. Packt mit an und tut Euren Teil.\n\nOh, ich vergaß: Macht Euch nicht über die Anfänger... ähhm, Anhänger der Seher lustig. Sieht aus, als würden wir in dieser Sache am selben Strang ziehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11482] = { id = 11482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflicht ruft", description = "Hört mich an, {race}.\n\nDie Pflicht verlangt, dass Ihr Euch zurück nach Azeroth begebt. Ein jeder, der dazu im Stande ist zu kämpfen, soll sich umgehend auf dem Sonnenbrunnenplateau melden.\n\nIch fürchte, dass ich Euch keine weiteren Informationen geben kann als diese:\n\nFür diese Mission werdet Ihr Euch mit den Aldor zusammentun. Sprecht mit einem Draenei namens Larethor, sobald Ihr dort ankommt.\n\nAnscheinend fordert die Situation, dass wir unsere Differenzen beiseite legen und uns zusammenschließen.\n\nMacht Euch bereit. Das hier klingt ernst.", sourceObjective = "Dathris Sonnensturm auf der Sehertreppe in Shattrath besteht darauf, dass Ihr umgehend nach Azeroth reist und Euch bei Larethor am Sonnenbrunnen meldet.", completion = "Willkommen auf dem Sonnenbrunnenplateau, Anfänger der... Wie bitte? Oh - Anhänger der Seher, natürlich. Habe ich das nicht gesagt?\n\nNun, gut, kommen wir gleich zur Sache. Hinter diesen Mauern geht es ernsthaft zur Sache, und das ist für unsere beiden Völker von großem Interesse. Und da keiner von uns über genügend Streitkräfte verfügt, um die Sache alleine anzugehen, werden wir ZUSAMMENARBEITEN. Verstanden?\n\nNa dann fangen wir doch einmal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[11488] = { id = 11488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrasse der Magister", description = "Willkommen am Sonnenbrunnen, {class}. Macht Euch mit der Umgebung vertraut und legt dort Hand an, wo Ihr nur könnt. Es gibt viel zu tun!\n\nIch? Ja, ich hätte da eine Kleinigkeit, die erledigt werden müsste, aber ich bin mir nicht sicher, ob Ihr der Aufgabe gewachsen wäret.\n\nWir hatten einen Kontaktmann auf der Terrasse der Magister im Einsatz, der uns diverse Informationen zukommen ließ. Er hat jedoch vor kurzem versäumt, uns Bericht zu erstatten, weswegen ich mir zunehmend Sorgen mache.\n\nDie Terrasse befindet sich gleich im Osten, die Anhöhe hoch. Die Informationen, die er gesammelt hat, sind entscheidend für unsere Mission.\n\nDenkt Ihr, dass Ihr damit zurecht kommt, {race}?", sourceObjective = "Exarch Larethor beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die Terrasse der Magister absucht und einen Blutelfenspion namens Tyrith findet.", completion = "...Kommt näher, {race}... Hört genau auf meine Worte...", sourceObjectiveStatus = "unverified-source-field" }
quests[11490] = { id = 11490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seher der Seher", description = "<Tyrith zuckt vor Schmerz zusammen, als er spricht.>\n\nGeht zur Terrasse... benutzt die Kugel.\n\n... Sie... sie speisen den Sonnenbrunnen...\n\n<Tyrith ringt nach Luft.>\n\nBeeilt Euch... Ihr müsst sie aufhalten... bevor sie...\n\n<Tyrith stirbt.>", sourceObjective = "Tyrith möchte, dass Ihr die Kugel auf dem Balkon auf der Terrasse der Magister benutzt.", completion = "Ich denke, dass es kein Zufall ist, dass sich unsere Wege heute kreuzen.\n\nIch meine zu erkennen, dass dies eine Fügung des Schicksals ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[11492] = { id = 11492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht totzukriegen", description = "Der Sonnenbrunnen heißt Euch willkommen, Sterbliche. Ihr trefft in der Tat zur rechten Zeit ein.\n\nWie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Findet ihn, Sterbliche. Noch einmal muss er aufgehalten werden.\n\nAndere Angelegenheiten von gleicher Dringlichkeit erfordern meine sofortige Aufmerksamkeit. Ich lege Kaels Schicksal in Eure Hände. Ihr dürft nicht versagen.\n\nMit etwas Glück werden wir uns wieder sprechen.", sourceObjective = "Kalecgos hat Euch damit beauftragt, Kael'thas auf der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor am Sammelpunkt der Zerschmetterten Sonne treffen.", progress = "Nun ja, {class}, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.\n\nWelch Kunde bringt Ihr mir?", completion = "<Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten auf der Terrasse der Magister berichtet.>\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.\n\nIch habe Euch unterschätzt, {race}. Bitte, nehmt dies im Namen der Sonnenbrunnenoffensive - eine Gabe, die eines Helden, wie Ihr einer seid, würdig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11496] = { id = 11496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barrieren des Sanktums", description = "Zuerst müssen wir das Sanktum der Sonnenweiten einnehmen. Sobald wir es gesichert haben, werden wir in der Lage sein, seine Energien für die Öffnung eines Portals nach Shattrath zu nutzen.\n\nDas Sanktum quillt über von Getriebenen - frühere Blutelfen, die zu hirnlosen Schatten ihrer selbst verkümmert sind. Die Verteidigungsanlangen hätten dieses Eindringen normalerweise verhindert, aber die Getriebenen haben die Energiequellen der Schutzbarrieren gestohlen.\n\nStellt den Getriebenen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt sie, um die Barrieren des Sanktums aufzuladen.", sourceObjective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr Manaüberreste von 4 getriebenen Unholden und getriebenen Verschlingern verschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche den Osten des Sanktums der Sonnenweiten umgeben.", completion = "Gute Arbeit, {name}.  Die Barrieren erhalten allmählich ihre Kraft zurück. Das Sanktum wird uns im Handumdrehen gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[11497] = { id = 11497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen lernen", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, der sein eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch zur Wildhammerfeste im Südwesten des Schattenmondtals begeben, und dort Ilsa Trubelbräu nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", sourceObjective = "Sprecht mit Ilsa Trubelbräu in der Wildhammerfeste im Schattenmondtal.", completion = "Ach, Nutral hat Euch also hierher geschickt? Sehr gut... Erinnert mich daran, dass ich ihm einen Krug Bier zum Dank für all die Fluglehrlinge, die er zu mir schickt, zukommen lasse.\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Niemand fliegt besser als die Wildhammer und diejenigen, die von uns ausgebildet wurden. Für ein Entgelt, ein nicht zu kleines wohlgemerkt, lehre ich Euch die Kunst des Fliegens!\n\nUnd wenn Ihr fertig seid, dann vergesst nicht mit Brunn zu sprechen - er hat ein paar schöne Greifen zur Auswahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[11498] = { id = 11498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen lernen", description = "Tja, mein Geschäft wird zwar auf die Dauer wohl eher darunter leiden, aber ich muss sagen, dass Ihr wie jemand ausseht, <der sein/die ihr> eigenes Reittier fliegen möchte, anstatt von Ort zu Ort geflogen zu werden.\n\nIch kann das gut verstehen.\n\nIhr, mein Freund, müsst Euch nach Schattenmond im Nordwesten des Schattenmondtals begeben, und dort Olrokk nach Flugstunden fragen. Die Ausbildung ist zwar nicht gerade billig, aber ich denke, dass es sich lohnen würde.", sourceObjective = "Sprecht mit Olrokk in Schattenmond im Schattenmondtal.", completion = "Blut und Donner, Nutral hat mir schon wieder einen Boden-Grunzer geschickt! Sehr gut... für einen Draenei.\n\n<Olrokk spuckt auf den Boden neben Euch.>\n\nWenn Ihr wissen wollt, wie man richtig fliegt, dann seid Ihr am richtigen Ort. Für einen großen Sack Gold bringe ich Euch genug bei, um nicht unehrenhaft in den Tod zu stürzen.\n\nUnd wenn Ihr fertig seid, dann vergesst nicht, Dama Wildmähne einen unserer Windreiter abzukaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11499] = { id = 11499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Siegelring von Prinz Kael'thas", description = "Heute werde ich das Unmögliche von Euch verlangen, {class}. Denn heute müsst Ihr mir den Siegelring von Kael'thas Sonnenwanderer, Lord der Blutelfen, beschaffen!\n\nEs ist wahr, die Gerüchte von seinem Tod waren aus der Luft gegriffen. Er ist nun einmal mehr erschienen - und diesmal auf der Terrasse der Magister auf der Insel von Quel'Danas. Was er dort macht, soll Euch jemand anderes berichten. Was ich weiß ist, dass es unzählig viele Sammler gibt, die an diesem Prinzenring interessiert sind. Und ich will ihnen diesen Ring beschaffen.\n\nOder, um genau zu sein will ich, dass Ihr ihn für mich beschafft.", sourceObjective = "Windhändler Zhareem hat Euch darum gebeten, ihm den Siegelring von Prinz Kael'thas zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.\n\nDiese Aufgabe kann nur auf der Terrasse der Magister und nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Die Terrasse der Magister muss in der Tat ein gefährlicher Ort sein - so nahe am Sonnenbrunnen, wie sie ist.\n\nIhr habt doch keine Bedenken, oder?", completion = "Der Blutelfenprinz ist also diesmal wirklich tot? Wie schade, ich dachte immer, dass er Klasse besäße. Wenn man sich denkt, dass jemand so erhaben für solch einen lumpigen Betrag zur Strecke gebracht werden konnte.\n\nAber es ist nun einmal so, wie man sagt: Geschäft ist Geschäft. Eure Belohnung ist verdient, Abenteuerer.\n\nKommt morgen wieder und ich werde einen anderen Auftrag für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11500] = { id = 11500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Schwestern der Qual", description = "Mah'duun vernahm eine Stimme, die ihm zuflüsterte, dass die Schwestern der Qual in die Hölle zurückgeschickt werden müssen, aus der sie kommen.\n\nMah'duun weiß, dass sich die Dämonen auf der Terrasse der Magister auf der Insel Quel'Danas befinden.\n\nIhr werdet Euch des Kopfgeldes wegen auf dieses Unterfangen einlassen oder auch nicht.", sourceObjective = "Netherpirscher Mah'duun möchte, dass Ihr 4 Schwestern der Qual erschlagt. Kehrt zu ihm in das untere Viertel in Shattrath zurück, sobald Ihr sie getötet habt, um das Kopfgeld einzufordern.", completion = "Wer weiß, weshalb die dämonischen Schwestern den Tod finden müssen? Sorgt Ihr Euch darum?\n\nMah'duun denkt, dass Ihr Euch jedoch genug darum sorgt, um das Kopfgeld einzustreichen.\n\nKommt morgen wieder und die Winde werden wieder zu Mah'duun gesprochen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11502] = { id = 11502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verteidigung von Halaa", description = "Wir sind kein kriegerisches Volk, {race}. Wenn der Krieg jedoch über unser Land kommt, rennen wir nicht vor ihm davon.\n\nDie Allianz und die Horde bekämpfen sich in der Stadt Halaa im Nordwesten. Wir wissen nicht, was die Blutelfen vorhaben, aber jeder Sieg, den die Horde erringt, wäre katastrophal. Die gemeinsame Geschichte unseres Volks mit den Orcs ist eine des Blutvergießens und des Verrats.\n\nGeht nun, streckt den Feind in Halaa nieder und Ihr werdet mit Münze, Ehre und Ruhm belohnt.", sourceObjective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Lakoor in Telaar zurück.", progress = "Ist Eure Aufgabe getan, {name}?", completion = "Ich danke Euch, {name}. Eure Mühen werden nicht unbeachtet bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11503] = { id = 11503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde - alte und neue", description = "Unser uralter Feind, die Draenei, sind mit mächtigen Verbündeten wiedergekehrt. Sie führen Krieg in Halaa, südwestlich von hier.\n\nSie dürfen nicht siegreich sein, denn Garadar wäre gewiss als nächstes dran.\n\nGeht und erschlagt diejenigen, die es wagen, unserem uralten Feind beizustehen.", sourceObjective = "Besiegt 10 feindliche Spieler in Halaa und kehrt zu Karrtog in Garadar zurück.", completion = "Ihr macht unserem Volk große Ehre. Ihr habt unseren Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[11505] = { id = 11505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister von Auchindoun", description = "Auchindouns Geister sind zwar nicht am Konflikt zwischen Allianz und Horde beteiligt, sollten wir sie jedoch auf unsere Seite ziehen können, hätten wir unseren Feinden gegenüber einen Vorteil in dieser Region.\n\nEin uralter Brauch führt die Lebenden auf den Pfad zu den Geistertürmen in der Knochenwüste, um den Geistern dort ihre Ehre zu erweisen - jedoch nur zu speziellen Tageszeiten. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werdet Ihr dadurch die Geister auf unsere Seite ziehen.\n\nSollten wir Erfolg damit haben, die Gunst der Geister zu erlangen, werden sie uns eine Wohltat erweisen, die unsere Bestrebungen unterstützen wird.", sourceObjective = "Helft der Allianz, einen Turm in der Knochenwüste zu sichern.", progress = "Die Geister sind ruhelos, {name}. Habt Ihr Eure Aufgabe vollbracht?", completion = "Die Geister sind ihrer Ruhe einen Schritt näher. Es ist gut, ihre Gunst zu erlangen - besonders dann, wenn so nahe an ihrer Ruhestätte Krieg geführt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11506] = { id = 11506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister von Auchindoun", description = "Die Draenei mögen unsere Feinde sein, aber die Geister ihrer Urahnen in Auchindoun sind rastlos und niemandem untertan.\n\nEin uralter Brauch der Draenei verlangt von ihnen, dass sie zu verschiedenen Tageszeiten bei den Geistertürmen in der Knochenwüste ihren Urahnen Respekt zollen. Wenn Ihr zu diesen Zeiten bei der Sicherung eines Turms helfen könnt, werden dadurch die Geister in Auchindoun zur Ruhe kommen.\n\nDie Allianz wird versuchen, die Türme einzunehmen, um die Gunst der Geister zu erlangen. Wir müssen sicherstellen, dass die Horde hier erfolgreich ist.", sourceObjective = "Helft der Horde, einen Turm in der Knochenwüste zu sichern.", progress = "Die Geister von Auchindoun sind um uns. Werden sie uns eine Wohltat zuteilwerden lassen?", completion = "Die Geister sind einen Schritt näher daran, ihre Ruhe zu finden, und haben uns deswegen ihre Gunst verliehen.\n\nEs muss eine Demütigung für unseren Feind sein, dass sich seine eigenen Urahnen gegen ihn wenden - auch, wenn es nur vorübergehend ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11513] = { id = 11513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manazellen abfangen", description = "Ich habe mir einen Plan ausgedacht, wie wir an eine Energiequelle kommen können, die stark genug ist, um unser Portal zu erschaffen.\n\nDie Streitmächte der Astralen auf dem Landeplatz von Bash'ir im Nordwesten des Schergrats schmuggeln Manazellen aus der Festung der Stürme heraus und schaffen sie in Kael'thas' Namen zum Sonnenbrunnen.\n\nSie haben die Zellen zwar versteckt, aber es gibt einen Weg, wie Ihr sie finden könnt. Die Astralen tragen Phasenvorrichtung bei sich, mit deren Hilfe Ihr die eingeschmuggelten Waren entdecken könnt.\n\nHütet Euch jedoch vor den Phasenwyrm, den Wächtern der Manazellen.", sourceObjective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", progress = "Habt Ihr die Manazellen?", completion = "Diese Manazellen sind von zentraler Bedeutung für unser Unterfangen. Das Portal zur Insel des Sonnenbrunnens wird im Nu geöffnet sein!\n\nKehrt morgen wieder zurück und ich werde Euch wieder aussenden, um noch mehr Zellen von unseren Bash'ir-'Freunden' zu beschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11514] = { id = 11514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sonnenbrunnenportal aufrechterhalten", description = "Wir müssen den Energiefluss zu unserem Portal aufrechterhalten oder es wird kollabieren. Die versteckten Manazellen der Astralen auf dem Landeplatz von Bash'ir werden den Zweck erfüllen. Der Landeplatz befindet sich weit im Norden auf dem Hochplateau in der nordwestlichen Ecke des Schergrats.\n\nBeschafft Euch eine Phasenvorrichtung von einem der Astralen und benutzt sie, um die Schmuggelwaren zu finden.\n\nNehmt Euch nur vor den Phasenwyrm in Acht, von denen sie die Manazellen bewachen lassen.", sourceObjective = "Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück.", progress = "{name}, wie steht es um die Manazellen, die Ihr heute für uns beschaffen wollt?", completion = "Diese Manazellen werden unser Portal weiterhin mit Energie speisen.\n\nKehrt morgen wieder zurück und ich werde Euch wieder auf Manazellensuche schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11515] = { id = 11515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut für Blut", description = "Als Kaels Streitmacht durch das Portal schritt, wurden seine loyalsten Lakaien auf eine entsetzliche Weise belohnt: Sie blieben zurück und soffen tagelang Dämonenblut.\n\nDas Blut hat sie verändert und ihnen neue Kräfte verliehen - es wird jedoch auch ihr Verderben sein.\n\nNehmt Blutproben von anderen Dämonen und benutzt sie, um den Teufelstrinker zu speisen und diese arroganten Narren ihrer Macht zu berauben. Tötet sie, sobald sie geschwächt sind. Kehrt dann zu mir zurück.", sourceObjective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe des Teufelstrinkers 4 ausgemergelte Getriebene des Teufelsbluts tötet. Um den Teufelstrinker zu speisen, benötigt Ihr das Dämonenblut von Racheherolden, die sich in der Nähe befinden.", progress = "Diese Monster sind eine Schande für unser Volk. Wir müssen sie vernichten, {name}.", completion = "Narren. Sie haben gelernt, wie man Teufelsenergie entzieht, aber nicht, wie man sie behält.\n\nWir haben Glück, {name}. Ein erfahrener Streiter des Teufelsbluts hätte gewiss einen beeindruckenden Gegner abgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11516] = { id = 11516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet den Durchgang", description = "Wir müssen diesen Durchgang schließen, damit die Legion keine Verstärkung mehr zur Insel von Quel'Danas schicken kann.\n\nNehmt diese Glutstücke, in ihnen befindet sich eine meiner Kreationen: ein lebendiges Leuchtfeuer. Es besitzt so lange eine mächtige zerstörerische Kraft, wie es mit genug Energie versorgt wird.\n\nFindet die Höllenfunken, die in dieser Gegend umherwandern, und erschlagt sie in der Nähe des lebendigen Leuchtfeuers. Mit jedem Male wird das Leuchtfeuer mächtiger - bis es instabil wird.\n\nSobald Ihr das geschafft habt, bringt Ihr das Leuchtfeuer zum Durchgang. Es wird dann wissen, was zu tun ist.", sourceObjective = "Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe der zischenden Glut ein lebendiges Leuchtfeuer beschwört und damit so lange glühende Höllenfunken in seiner Nähe tötet, bis es zu einem instabilen lebendigen Leuchtfeuer wird. Kehrt anschließend mit letzterem zum Durchgang der Legion zurück und zerstört ihn.", progress = "Ist es vollbracht, {name}? Kael'thas darf keine weitere Verstärkung durch die Legion erhalten.", completion = "Ausgezeichnete Arbeit, {name}. Die Dämonen werden den Durchgang wohlmöglich rechtzeitig reparieren. Na dann werden wir ihn wohl noch einmal in die Luft jagen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11517] = { id = 11517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Nasuun", description = "Ich bin so froh, dass Ihr hier seid, {class}! Nun, da wir das Sanktum eingenommen haben, müssen wir uns schleunigst daran machen, ein magisches Portal zu öffnen, das von Shattrath in der Scherbenwelt aus hier her führt.\n\nMein Lehnsherr Exarch Nasuun will mit Hilfe der Offensive genau das tun. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Öffnung des Portals zu helfen.\n\nReist nach Shattrath und sprecht mit ihm. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.", sourceObjective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", completion = "Portanuus hat Euch geschickt? Gut, wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[11520] = { id = 11520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die eigenen Wurzeln entdecken", description = "Grüße, {race}.\n\nLeider kann ich Euch nichts anbieten, solange ich keine Reagenzien auf Lager habe.\n\nEines der benötigten Reagenzien ist eine Besonderheit. Es trägt den Namen Messerdornwurzel und ist besonders schwierig zu sammeln.\n\nZum Glück kenne ich da ein Geheimnis...\n\nMan benutzt einfach die Drüsen eines Messerdornschinders, um auf diese Weise einen Hetzer zu kontrollieren, der dann eine Wurzel freilegt.\n\nWenn Ihr die Wurzeln finden wollt, dann müsst Ihr in die Scherbenwelt reisen und von Shattrath aus gen Nordosten fliegen, bis Ihr die Messerdornhöhen erreicht.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt.", progress = "Ich bitte Euch, {name}. Ich bin viel zu beschäftigt, als dass ich mich auf unnützes Geschwätz einlassen würde.\n\nLasst es mich wissen, sobald Ihr die besagten Wurzeln eingesammelt habt.", completion = "Das sollte funktionieren, {class}.\n\nIch bedanke mich für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11521] = { id = 11521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Wurzeln wiederentdecken", description = "Ich verfüge im Moment über genug Vorräte. Ich werde jedoch eine Menge Messerdornwurzeln benötigen, um der Nachfrage nachzukommen.\n\nMan benutzt einfach die Drüsen eines Messerdornschinders, um auf diese Weise einen Hetzer zu kontrollieren, der dann eine Wurzel freilegt.\n\nWenn Ihr die Wurzeln finden wollt, dann müsst Ihr in die Scherbenwelt reisen und von Shattrath aus gen Nordosten fliegen, bis Ihr die Messerdornhöhen erreicht.\n\nKehrt zu mir zurück, {name}, sobald Ihr fünf dieser Wurzeln gesammelt habt.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt.", progress = "Ich bitte Euch, {name}. Ich bin viel zu beschäftigt, als dass ich mich auf unnützes Geschwätz einlassen würde.\n\nSagt mir Bescheid, sobald Ihr die besagten Wurzeln eingesammelt habt.", completion = "Ausgezeichnete Arbeit, {name}.\n\nDanke noch mal für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[11523] = { id = 11523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fahrt die Barrieren hoch!", description = "Wir haben die Kristallbarrieren um das Sanktum erfolgreich reaktiviert, aber warum hier aufhören?\n\nWir werden Verteidigungen um die anderen Gebäude herum aufbauen, aber die Getriebenen sind dickköpfig und stehlen weiterhin Energie von den Kristallbarrieren.\n\nStellt ihnen nach und holt Euch die Manaüberreste, die sie bei sich tragen. Benutzt die Überreste, um die Barrieren des Sanktums zu energetisieren, die Sicherheit unseres Vorhabens hängt davon ab.", sourceObjective = "Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr Manaüberreste von 4 getriebenen Unholden und Verschlingern beschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche die Gebäude der Sonnenweiten umgeben.", progress = "Habt Ihr eine Kristallbarriere reaktiviert, {name}?", completion = "Gute Arbeit, {name}.  Die Barrieren erhalten allmählich ihre Kraft zurück. Die Sonnenweiten werden uns im Handumdrehen gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[11524] = { id = 11524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberechenbares Verhalten", description = "Wir sind zwar nicht genug, um das Sanktum der Sonnenweiten einzunehmen, aber ich habe einen Plan, mit dem wir den Kampf zu unseren Gunsten wenden können.\n\nDie unkontrollierten Energien des Sonnenbrunnens verursachten Fehlfunktionen bei den Wachposten, die auf dieser Insel patrouillieren. Die Kristallkerne, die ihr Verhalten steuern, sind irreparabel beschädigt.\n\nIch habe neue Kristalle angefertigt, mit denen wir sie unter unsere Kontrolle bringen werden. Steckt die Kristalle ins Innere der besiegten Wachposten. Wir benötigen jede Hilfe, die wir bekommen können.", sourceObjective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", progress = "Habt Ihr die Wachposten konvertiert, {name}?", completion = "Gute Arbeit, {name}. Das Sanktum wird im Nu unser sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11525] = { id = 11525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Konvertierungen", description = "Mein Plan, die beschädigten Kristalle der unberechenbaren Wachposten auszutauschen, hat funktioniert. Wir konnten mit ihrer Hilfe das Sanktum der Sonnenweiten einnehmen.\n\nIch habe neue Kristalle angefertigt, die noch mehr von ihnen unter unsere Kontrolle bringen werden. Platziert diese im Inneren besiegter Wachposten. Wir werden sie dann an verschiedene Orte entsenden, um sie dort einzusetzen, sobald sie konvertiert sind.", sourceObjective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", progress = "Habt Ihr die Wachposten konvertiert, {name}?", completion = "Ausgezeichnet. Die konvertierten Wachposten werden uns bei der Sicherung unseres Gebiets helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11526] = { id = 11526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Magistrix wird vermisst", description = "Wir haben eine unserer Agentinnen ausgesandt, um das Teufelsportal in der Mitte des im Süden gelegenen Platzes der Morgenröte zu untersuchen. Sie ist noch nicht zurückgekehrt.\n\nNehmt diese Schriftrolle - eine der Leichen des Feindes trug sie bei sich. Wir nehmen an, dass sie Euch den Zugang durch das Portal gewährt. Schreitet durch das Portal, spürt Magistrix Seyla auf und helft, so gut Ihr nur könnt.", sourceObjective = "Benutzt die erbeutete Schriftrolle der Legion in der Nähe des Portals auf dem Platz der Morgenröte. Findet Magistrix Seyla, sobald Ihr auf der anderen Seite des Portals seid.", progress = "Seid still, {class}. Die Truppen der Legion bewachen die Gegend südlich des Tors.", completion = "Es ist lieb von Theris, dass er sich um mich Sorgen macht, aber wir haben hier größere Probleme - viel größere.", sourceObjectiveStatus = "unverified-source-field" }
quests[11528] = { id = 11528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11531] = { id = 11531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Motorteil", description = "Dieses seltsame Motorteil sieht zwar nicht so aus, als würde es in eine Dampfpumpe passen, jedoch scheint alles andere, was Ihr so herumliegen seht, noch weniger dafür geeignet zu sein. Vielleicht weiß K. Lee Kleinfrey mehr darüber.", sourceObjective = "Bringt K. Lee Kleinfrey in Telredor das seltsame Motorteil.", progress = "Du meine Güte! Was habt Ihr denn da, {name}?", completion = "<K. Lee sieht sich das Motorteil an und wirkt für einen Moment abwesend.>\n\nDas ist mal was echt Besonderes. Hm, schwer zu sagen, woher das Ding kommt. Ich behalte es erst einmal für mich und werde Euch für die Unannehmlichkeiten entschädigen.\n\nAber unter uns gesagt, denke ich, dass es am besten wäre, wenn wir niemandem davon erzählen.\n\n<K. Lee zeigt Euch ihr bestes Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11532] = { id = 11532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablenkungsmanöver an der Todesschneise", description = "Die Legion wird uns angreifen, sobald ihre Truppen im Süden nicht mehr gebunden sind. Im Moment hält die Geißel in der Todesschneise ihre Streitkräfte beschäftigt. Jedoch nicht mehr lange.\n\nIch möchte, dass Ihr mit einem Drachenfalken über die Schneise hinwegfliegt und die Dämonen mit Hilfe dieser arkanen Ladungen dezimiert.\n\nWenn alles gut geht, werden Kaels Lakaien es nicht einmal bemerken, wenn wir die Waffenkammer einnehmen. Sprecht mit Ayren, dem Drachenfalkenmeister im westlichen Teil des Hafens, sobald Ihr bereit seid loszufliegen.", sourceObjective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mit Hilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", progress = "Habt Ihr Eure Mission erfüllt, {name}?", completion = "Ihr habt echtes Talent, muss ich sagen. Habt Ihr schon mal daran gedacht, der Himmelswache beizutreten?\n\nDas war nur Spaß, {name}. Wir benötigen Euch hier, wenn wir das Dock irgendwann einmal in naher Zukunft einnehmen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11533] = { id = 11533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luftangriffe müssen weitergehen", description = "Dank unserer Luftangriffe gegen die Truppen der Legion in der Todesschneise konnten wir dem Feind die Waffenkammer abjagen.\n\nTatsächlich lief die Sache so gut, dass wir unsere Luftangriffe gegen sie weiterführen werden. Nehmt diese arkanen Ladungen und verwendet sie gegen ihre Truppen.\n\nSprecht mit Ayren Wolkenbrecher im Hafen der Sonnenweiten, sobald Ihr abflugbereit seid.", sourceObjective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mit Hilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", progress = "Habt Ihr Eure Mission erfüllt, {name}?", completion = "Dämonen, die wir heute töten, sind Dämonen, die wir morgen nicht mehr bekämpfen müssen. Weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[11534] = { id = 11534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Nasuun", description = "Ich bin so froh, dass Ihr hier seid, {class}! Nachdem wir dieses Sanktum den Getriebenen weggenommen hatten, beeilten wir uns, ein Portal zu erschaffen, das von Shattrath in der Scherbenwelt aus hierher führt.\n\nMein Lehnsherr Exarch Nasuun leitet die Bemühungen der Offensive, dieses Portal aufrecht zu erhalten. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Energieversorgung des Portals behilflich zu sein.\n\nReist nach Shattrath und sprecht mit Nasuun. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.", sourceObjective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", completion = "Portanuus hat Euch geschickt? Gut, wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[11535] = { id = 11535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen", description = "Versorgungsgüter sind auf dem Weg hierher - wird mir zumindest gesagt.\n\nTrotzdem können wir es uns nicht leisten, hier zu warten und zu hoffen, dass Hilfe kommen wird, bevor die Offensive zum Stillstand kommt. Wir müssen das Beste aus dem machen, was uns gegeben ist.\n\nFür meinen Teil benötige ich Erz, um daraus einen Amboss zu fertigen und anzufangen, unsere Rüstungen und Waffen aufzubessern.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt.\n\nWenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", sourceObjective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, 3 Stück Erz aus ihren Truhen zu stehlen.", progress = "Habt Ihr das benötigte Erz eingesammelt?", completion = "Ausgezeichnet! Wir kommen voran...\n\nBald werde ich einen Amboss herstellen können - und die eigentliche Arbeit kann beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11536] = { id = 11536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hört jetzt nicht auf!", description = "Da wir jetzt einen Amboss haben, kann ich so richtig anfangen zu arbeiten.\n\nIch werde das Eisenerz der Dunkelflossen immer gut gebrauchen können, egal wie viele Versorgungsgüter wir bekommen. Wenn wir hier gewinnen wollen, dann benötigen wir regelmäßige Waffen- und Rüstungslieferungen.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt. Wenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", sourceObjective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, um 3 Stück Erz aus ihren Truhen zu stehlen.", progress = "Habt Ihr das Erz, nach dem ich Euch gefragt habe, eingesammelt?", completion = "Ausgezeichnet! Damit werde ich Rüstungen und Waffen für unsere Soldaten herstellen können.\n\nEure Hilfe ist Gold wert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht muss weitergehen", description = "Wir müssen zusehen, dass wir die Armeen der Legion weiterhin besiegen und entmutigen.\n\nDie Abgesandten des Hasses sind Stoßtruppen der Legion, die immer dann eingesetzt werden, wenn ihre Streitkräfte erhebliche Verluste zu verzeichnen haben. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen auf dem Platz der Morgenröte. Tötet den Abgesandten, sobald Ihr ihm begegnet, und spießt anschließend seinen Körper auf.", sourceObjective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", progress = "Wart Ihr erfolgreich, {name}?", completion = "Euer Engagement ist beispielhaft, {name}. Wir werden den Streitkräften der Brennenden Legion zeigen, wozu wir im Stande sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Waffenkammer der Sonnenweiten", description = "Die Brennende Legion hält die Waffenkammer der Sonnenweiten - sie ist von taktischer Wichtigkeit für unseren Einsatz. Solange ihre Moral hoch bleibt, werden wir das Gebäude ihrem Griff nicht entziehen können.\n\nDie Abgesandten des Hasses sind Elitestoßtruppen der Legion, die als Verstärkung für taktisch wichtige Stellungen eingesetzt werden. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen der Legion. Tötet den Abgesandten, sobald Ihr ihm begegnet, und durchspießt seinen Körper.", sourceObjective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte oder der Waffenkammer der Sonnenweiten niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", progress = "Habt Ihr getan, worum ich Euch gebeten habe, {name}?", completion = "Euer Engagement ist beispielhaft, {name}. Wir werden die Waffenkammer in kürzester Zeit aus den Klauen der Streitkräfte der Brennenden Legion befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hafen einnehmen", description = "Die Armee der Dämmerklingen - sie gehört zu Kaels Elitestreitkräften - wurde im Hafen der Sonnenweiten und in Morgenstern stationiert.\n\nDer Hafen ist von höchster strategischer Bedeutung für unsere Pläne. Je mehr Dämmerklingen Ihr also beseitigt, umso mehr helft Ihr uns damit. Kael'thas wird den Tag bereuen, als er sich von seinem Volk abwandte und sich mit der Brennenden Legion einließ.", sourceObjective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Schützen der Dämmerklingen niederstreckt.", completion = "Ausgezeichnete Arbeit, {class}. Kaels Armeen werden ins Wanken geraten und sobald wir den Hafen eingenommen haben, werden wir ihnen den Todesstoß verpassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11540] = { id = 11540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Dämmerklingen", description = "Wir haben die Armee der Dämmerklingen aus dem Hafen der Sonnenweiten vertrieben. Die Sonnenweiten gehören nun uns. Doch... bin ich nicht vollends zufrieden.\n\nIch möchte, dass Ihr Euch ins westlich gelegene Morgenstern begebt und jeden überlebenden Anhänger der Dämmerklingen erschlagt, der Euch über den Weg läuft. Sie besiegelten ihr Schicksal, als sie Kael an diesen Ort folgten.", sourceObjective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Bogenschützen der Dämmerklingen niederstreckt.", completion = "Was geht nur durch Prinz Kael'thas Sonnenwanderers Kopf, wenn er von den Niederlagen seiner Armeen erfährt?\n\nIst es Verzweiflung? Hilflosigkeit? Furcht?\n\nIch hoffe doch, dass dem so ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11541] = { id = 11541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belästigung an der Küste der Grünkiemen", description = "Die Naga haben die Küste der Grünkiemen im Südosten erobert. Ihre Frauen, die Sirenen der Dunkelflossen, haben die Murlocs bezaubert und zu ihren Sklaven gemacht.\n\nEs ist meine Pflicht, dafür zu sorgen, dass das, was auch immer die Naga dort treiben, gestört wird. Hier kommt Ihr ins Spiel.\n\n{class}, ich möchte, dass Ihr den weiblichen Naga die Kontrollkugeln abnehmt und sie auf den Boden in der Nähe der Grünkiemensklaven werft, damit die Kugel zerspringt und die Murlocs befreit werden.\n\nIch nehme an, dass die Murlocs erbost sein werden und sich gegen ihre Meister wenden werden.", sourceObjective = "Kapitän Valindria möchte, dass Ihr 10 Grünkiemensklaven befreit und zu ihr zurückkehrt, sobald Ihr damit fertig seid. Sie befindet sich auf der 'Silbermonds Stolz' im Hafen der Sonnenweiten.", completion = "Das reicht für heute. Zeit und Regelmäßigkeit ist hier der Schlüssel zum Erfolg. Wenn wir sie zu sehr belästigten, würden sie ihre Aufmerksamkeit direkt auf uns richten - und das wollen wir nicht.\n\nKommt morgen wieder zurück, damit wir für ein wenig mehr Belästigung sorgen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11542] = { id = 11542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Verstärkung auf", description = "Wir stoßen vor und nehmen den Hafen als nächstes ein, um unsere Kontrolle über die Sonnenweiten zu festigen. Leider ist eine Flotte Schiffe mit Reservisten der Dämmerklingen auf dem Weg dorthin, um Kaels Truppen zu verstärken.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie sich nicht großartig verteidigen können.", sourceObjective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet. Fliegt dann über die Unterstützungsflotte der Dämmerklingen hinweg und benutzt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", progress = "Konntet Ihr Eure Aufgabe erfüllen, {name}?", completion = "Gut gemacht, {name}. Es sollte eine Weile dauern, bis irgendwelche Verstärkungstruppen im Hafen ankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11543] = { id = 11543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind vom Leibe halten", description = "Wir konnten die Sonnenweiten vollständig einnehmen. Leider hat sich eine Flotte Schiffe mit Reservisten der Dämmerklingen auf den Weg gemacht, um den Hafen einzunehmen.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie keine wirkliche Gegenwehr starten können.", sourceObjective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet und über die Flotte mit Verstärkungstruppen der Dämmerklingen hinwegfliegt. Benutzt solange Ihr fliegt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", progress = "Konntet Ihr Eure Aufgabe erfüllen, {name}?", completion = "Gut gemacht, {name}. Es sollte eine Weile dauern, bis irgendwelche Verstärkungstruppen im Hafen ankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11544] = { id = 11544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen von Ata'mal", description = "Die Terrasse von Ata'mal im Osten des Schattenmondtals ist den Draenei heilig. Derzeit ist sie jedoch von Höllenorcs besetzt, die das spezielle Erz, das dort vorkommt, geschürft und daraus Waffen und Rüstungen der Verderbnis hergestellt haben.\n\nIch brauche die Waffen, um eine Legierung mit Nagaerz herzustellen. Unsere Anachoreten haben meinen Amboss mit der Fähigkeit gesegnet, sie zu reinigen.\n\nIhr könnt die Waffen an den Auserwählten, Tötern und Dunkelwirkern des Schattenmondklans finden. Bringt sie hierher, zerlegt und reinigt sie auf meinem Amboss und übergebt mir das gereinigte Resultat.", sourceObjective = "Schmiedin Hauthaa möchte, dass Ihr 5 Stück gereinigtes Metall von Ata'mal herstellt. Um dies zu tun, müsst Ihr Waffen von Ata'mal auf ihrem Amboss in der Waffenkammer der Sonnenweiten auf der Insel von Quel'Danas zerlegen.", progress = "{class}, ich brauche so viel gereinigtes Metall von Ata'mal, wie nur möglich.", completion = "Ich danke Euch, Freund. Nun werde ich mehr von der speziellen Legierung herstellen können, die zur Herstellung der Waffen und Rüstungen unserer Streitkräfte verwendet wird.\n\nAußerdem habe ich hier ein wenig von dem Extrakt, das bei der Herstellung übrig geblieben ist. Ihr werdet es wahrscheinlich sehr nützlich für Eure Waffen finden. Wählt bitte das aus, was Euren Zwecken am besten dient.\n\nKehrt zu mir am morgigen Tage zurück. Ich werde mit Sicherheit mehr Waffen benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11545] = { id = 11545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine milde Gabe", description = "Wir haben die Sonnenweiten dem Feind entrissen - der endgültige Sieg steht kurz bevor. Der Preis war hoch und viele tapfere Kämpfer gaben dafür ihr Leben.\n\nMein Ziel ist es, sicherzustellen, dass die Gefallenen nicht vergessen werden. Also bitte ich Euch, dass Ihr einen Moment innehaltet, um über eine Spende für eine Gedenkstätte nachzudenken. Alles übrig gebliebene Gold wird an die Witwen und Waisen der Gefallenen gehen.", sourceObjective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", progress = "Wollt Ihr eine Spende machen?", completion = "Ihr seid eine tugendhafte Seele, {name}. In Zeiten des Krieges und Triumphs werden die Gefallenen nur zu leicht vergessen. Die Freunde und Familien der Toten danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11546] = { id = 11546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschäft geöffnet", description = "Willkommen, {name}.\n\nEs gibt mehrere Möglichkeiten, wie ich Euch bei Eurem Unterfangen behilflich sein kann.\n\nIch habe zum Beispiel vor kurzem ein Rezept für ein einzigartiges Elixier entdeckt.\n\nDie Blutbeere ist in vielen Regionen Azeroths ein wildes Gewächs und wurde sehr lange als lästig empfunden. Ich habe jedoch herausgefunden, dass die Pflanze, wenn sie den Kräften des Sonnenbrunnens ausgesetzt wird, besondere Eigenschaften annimmt, die destilliert und anschließend getrunken werden können, um die eigenen Fähigkeiten zu verstärken.\n\nGeht zu den Büschen in der Nähe und bringt mir eine Probe - dann werdet Ihr sehen, was ich meine.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr 5 Blutbeeren von den Büschen auf Quel'Danas sammelt.", progress = "Habt Ihr diese Beeren schon gesammelt?", completion = "Ausgezeichnet, {name}.\n\nIch hoffe, dass Euch dies bei Eurem Unterfangen helfen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11547] = { id = 11547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne deine Leylinien", description = "Trittbrettfahrer!\n\nAlle wollen sie ihre Wünsche sofort erfüllt haben, ohne auch nur einen Gedanken daran zu verschwenden, wie viel Anstrengung selbst im einfachsten Portal steckt.\n\nVielleicht wird Euch etwas Aufklärung ein wenig mehr Dankbarkeit für meine unermüdlichen Anstrengungen beibringen.\n\nNehmt diesen Kristall und stimmt ihn auf den Blutkristall im Westen ab. Dieselbe Prozedur müsst Ihr dann am Portal auf dem Platz der Morgenröte im Süden und in der Nähe des Nagaschreins an der Küste der Grünkiemen im Südosten wiederholen.\n\nVielleicht werdet Ihr dann Eure heiß geliebten Translokationen mehr schätzen...", sourceObjective = "Astromant Darnarian im Sanktum der Sonnenweiten möchte, dass Ihr den Kristall des Astromanten am Blutkristall, am Portal auf dem Platz der Morgenröte und in der Nähe des Nagaschreins an der Küste der Grünkiemen benutzt.", progress = "Habt Ihr den Kristall schon ausgerichtet, {class}?", completion = "Ja, ja. Sehen wir uns das doch einmal an.\n\nAlles scheint in Ordnung zu sein. Also gut. Hier ist Euer Translokator.\n\nWenn auch nur ein Teil Eurer Messungen fehlerhaft ist, dann ist es unvorhersehbar, wo genau Ihr landen werdet. Aber dann wäret Ihr wohlgemerkt selber schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11548] = { id = 11548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure weitere Unterstützung", description = "Wir haben den Gefallenen zu Ehren ein Denkmal errichtet - ein kleiner Trost für die Familien, die ihre Angehörigen verloren haben.\n\nIch werde damit beginnen, Spenden zu sammeln, um die Waisen und Ehepartner unserer Kriegshelden zu unterstützen. Falls Ihr eine kleine Spende machen könntet, würdet Ihr viel dazu beitragen.", sourceObjective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", progress = "Wollt Ihr eine Spende machen?", completion = "Ihr seid eine tugendhafte Seele, {name}. In Zeiten des Krieges und Triumphs werden die Gefallenen nur zu leicht vergessen. Die Freunde und Familien der Toten danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11549] = { id = 11549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großmütiger Spender", description = "Ihr habt viel für uns getan, {name}. Wir sind Euch für Eure Unterstützung sehr dankbar.\n\nIhr habt vielleicht bemerkt, wie sich die Anachoretin Ayuri dort draußen bemüht. Sie hat ein großes Herz und ist sehr überzeugend, aber die Spenden kommen nicht gerade an das heran, was sie sich erhofft hatte.\n\nFalls Ihr eine große Spende machen würdet, um ihre Sache zu unterstützen, werde ich mich persönlich dafür stark machen, dass Eure Taten in diesem Krieg weit und breit bekannt sein werden. Was sagt Ihr dazu?", sourceObjective = "Anachoret Kairthos möchte, dass Ihr 1000 Gold spendet, um Anachoretin Ayuri in ihrem Vorhaben zu unterstützen. Wenn Ihr die Aufgabe abschließen solltet, werdet Ihr den Namen \"{name} der Zerschmetterten Sonne\" tragen.", progress = "Seid Ihr bereit dazu, den Beitrag zu leisten?", completion = "Ihr seid wahrhaftig eine großzügige Person und ein würdiger Verbündeter. Von nun an sollt Ihr als \"{name} der Zerschmetterten Sonne\" bekannt sein. All diejenigen, die hier kämpften, werden von Euren Taten wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11550] = { id = 11550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Betrüger betritt die Bühne...", description = "Kael'thas' finstere Pläne konnten unseren größten Anstrengungen zum Trotz ausgeführt werden. Der Sonnenbrunnen wurde wieder entfacht, um die Ankunft des Betrügers vorzubereiten.\n\nDer Gegenstand, der vor mir steht und über dem A'dal schwebt, repräsentiert den derzeitigen Status der Verteidigungsanlagen des Sonnenbrunnens. Es wurden riesige Barrieren errichtet, um unsere Angriffe auf die inneren Hallen zu behindern. Wenn unsere Welt jemals Hilfe benötigen sollte, dann wäre es jetzt.\n\nMeldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas nördlich von Quel'Thalas.", sourceObjective = "Meldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas, nördlich von Quel'Thalas.\n\nSprecht mit Flugmeistern in Eisenschmiede und Silbermond, sie werden Euch dorthin bringen.", completion = "Kil'jaeden stürzt sich mit der geballten Kraft der Brennenden Legion auf diese Welt. Sollte er beschworen werden, wird unsere Welt abermals im Chaos versinken. Eure Unterstützung auf der Insel von Quel'Danas ist entscheidend für unseren Sieg über die Legion.\n\nUnsere Magier arbeiten daran, die Barrieren zu durchbrechen, die uns den Zugang zum Sonnenbrunnen versperren. Leistet Euren Beitrag im Kampf gegen die Streitkräfte der Legion, indem Ihr der Offensive der Zerschmetterten Sonne helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[11554] = { id = 11554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund an der Front", sourceObjective = "Euer Beitrag zur Offensive wurde nicht übersehen, {name}. Die vereinten Kräfte der Aldor und Seher bedanken sich bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11555] = { id = 11555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Verbündeten wollen Euer Wohl", sourceObjective = "Ihr beweist Euch weiterhin als würdig in dieser überaus wichtigen Schlacht, {name}. Bitte nehmt dies als Zeichen unserer fortwährenden Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11556] = { id = 11556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld zollt man Euch Respekt", sourceObjective = "Ohne Euch hätten wir nie so weit kommen können, {name}. Die vereinten Kräfte der Aldor und Seher sind nicht genug, um die Legion und Kael zu vernichten. Wir sind froh darüber, Verbündete von Eurem Kaliber unter uns zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11557] = { id = 11557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Kämpfer begegnen Euch mit Ehrfurcht", sourceObjective = "Ihr seid einer unserer allerbesten Kämpfer, {name}. In unserer Armee wird man Euren Namen nicht so schnell vergessen.\n\nIm Namen unserer Streitkräfte bitte ich Euch, dieses kleine Geschenk entgegenzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11558] = { id = 11558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas Unnatürliches an sich. Sie ist abscheulich und hat sie erst einmal unsere Verteidigung geschwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits so viele unserer Leute von diesem lächerlichen Verhalten befallen sind. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser Dummheit befallen wurde.", sourceObjective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11580] = { id = 11580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Horde im Silberwald!", sourceObjectiveStatus = "unverified-source-field" }
quests[11581] = { id = 11581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz in Westfall!", sourceObjectiveStatus = "unverified-source-field" }
quests[11583] = { id = 11583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme von Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[11584] = { id = 11584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme des Silberwaldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11657] = { id = 11657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackeln fangen", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Freudenfeuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier nacheinander und kommt wieder zu mir zurück.\n\nSeid vorsichtig! Die Fackeln sind gefährlich, wenn sie auf dem Boden aufkommen! Und fangt sie alle auf! Wenn eine davon auf den Boden fällt, müsst Ihr zurück zum Freudenfeuer und von vorn anfangen. Viel Glück.", sourceObjective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11665] = { id = 11665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokilisken in der Stadt", description = "Hallo, <Junge/Mädchen>. Ich bin froh, dass Ihr vorbeigeschaut habt, um mit einem alten Mann zu sprechen - zuhause gibt es Schwierigkeiten.\n\nEin fliegender Händler hat neulich eine Ladung Krokiliskenbabys an ein paar leichtgläubige Kinder verkauft. Krokilisken sind wilde Bestien. Viele sind entkommen und halten sich jetzt in den Wasserwegen der Stadt verborgen.\n\nNehmt Eure stärkste Angelrute, werft sie in Sturmwind oder Orgrimmar aus und bringt einen der kleinen Teufel zurück zu mir. Ich kann es kaum erwarten, einen zu sehen.", sourceObjective = "Bringt dem alten Barlo ein Krokiliskenbaby. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Schon Kroks in den Abwasserkanälen gefangen?", completion = "Was für eine miese kleine Kreatur! Ich bin mir sicher, dass der Rokk irgendwas Leckeres aus ihr machen wird.\n\nIch mach natürlich nur Spaß.\n\n<Der alte Barlo zwinkert neckisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11666] = { id = 11666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köderbanditen", description = "Ihr wisst wahrscheinlich alles über den goldenen Stachelflosser - in den Flüssen von Terokkar kommen sie recht häufig vor, außerdem sind sie eine Delikatesse für Priester. Es gibt jedoch einen, von dem Ihr noch nicht gehört habt: den schwarzen Stachelflosser.\n\nDer Fisch ist berüchtigt für seine Gerissenheit und dafür, dass er schwierig einzufangen ist. Ihr müsst Eure Angelschnur in letzter Sekunde einziehen, denn sie knabbern am Köder, bevor sie sich ihn schnappen.\n\nWerft Eure Angelrute in den Gewässern von Terokkar aus und bringt mir einen schwarzen Stachelflosser. In Seen braucht Ihr gar nicht erst zu suchen - der Flitzer kommt nur in Fließgewässern vor.", sourceObjective = "Bringt dem alten Barlo einen schwarzen Stachelflosser. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Wie fischt sich's denn heute, mein Junge?", completion = "Nun sieh mal einer an... Ihr habt einen Großen gefangen! Dieser alte Mann wird heute Abend gut essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11667] = { id = 11667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eine, der entkam", description = "Feigenschimmers Matschflosser ist ein erstaunlich schneller Gründler, den man in den Gewässern von Nagrand anfindet. Sie wachsen ihr ganzes Leben lang und sind als Kämpfer sehr bekannt.\n\nVor Jahren fing ich den größten Matschflosser der Welt, da bin ich mir sicher... Doch dann brachte er meine Leine zum Reißen und kam davon.\n\nEinem Angler Eures Kalibers muss man nicht sagen, was zu tun ist - Euer Schicksal erwartet Euch an den Seen von Nagrand.", sourceObjective = "Fangt den größten Matschflosser der Welt und bringt ihn zum alten Barlo. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Sagt mir, dass Ihr ihn gefangen habt. Bitte sagt mir, dass Ihr den Mistkarpfen gefangen habt.", completion = "Da ist er! Diese Narbe würde ich immer wiedererkennen.\n\nAber um ganz ehrlich zu sein, habe ich ihn mir... größer vorgestellt. Tja - denke, dass ich ihn freilassen und es an einem anderen Tag noch einmal versuchen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11668] = { id = 11668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnelenfangen ist nicht einfach", description = "In den Seen der Zangarmarschen gibt es viele große Fische. Habt Ihr Euch jemals darüber Gedanken gemacht, was sie fressen?\n\nGarnelen - riesige Süßwassergarnelen. Der Rokk hat mir erzählt, dass man unendlich viele Garnelengerichte zubereiten kann.\n\nGarnelen sind jedoch zu klein, als dass man sie mit einer Angelschnur fangen könnte. Hier also der Trick: Schneidet eine aufgedunsene Stachelkiemenforelle auf und Ihr werdet, wenn Ihr Glück habt, die eine oder andere Garnele darin finden.", sourceObjective = "Bringt dem alten Barlo 10 riesige Süßwassergarnelen. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Was haben wir denn heute gefangen, mein Junge?", completion = "Ihr könnt mit Haken und Messer gut umgehen. Reicht mir die süßen Leckerbissen und ich werde Euch davon kosten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11669] = { id = 11669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsblutfilet", description = "Dieser alte Mann wird bald jagen gehen. Ich werde mir vor Azsharas Küste einen Mammuthai fangen.\n\nDie Sache ist nur, dass ich ein Toxin benötige, das auf einer Speerspitze haften bleibt, wenn man sich unter Wasser befindet. Um so etwas herzustellen, benötige ich die Drüsen eines giftigen Fischs: dem Teufelsblutschnapper.\n\nSolch ein abscheulicher Fisch gedeiht nur in den Gewässern der Höllenfeuerhalbinsel und des Schattenmondtals. Bringt mir das Mordsding und ihr macht aus mir einen glücklichen alten Mann.", sourceObjective = "Bringt dem alten Barlo einen monströsen Teufelsblutschnapper. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Der Teufelsblut ist ein Wunder der Evolution. Er kann in allen Gewässern und sogar Lava überleben. Fischer sind seine einzigen natürlichen Feinde.\n\nGlück beim Beutefang gehabt?", completion = "Das ist der größte und hässlichste Fisch, den ich je gesehen habe. Ich kann mir gar nicht vorstellen, was Ihr als Köder benutzt habt.\n\nLegt das Biest einfach auf den Boden und ich werde mich darum kümmern, sobald ich mir sicher sein kann, dass es tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11691] = { id = 11691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwört Ahune", description = "Ich und meine Schamanen haben all unsere Kräfte für die Schlacht mit dem Frostfürsten gesammelt. Ihr werdet die Faust der Erdenmutter sein, {name}.\n\nNehmt dieses Magmatotem und benutzt es in der Nähe des Eisbrockens im Nordosten. Ahune leitet seine Kraft durch diesen Brocken. Unsere Hoffnung ist, dass das Totem seine Verbindung mit der Elementarebene durchtrennen wird.\n\nWenn wir Glück haben, dann könnten wir ihn vielleicht besiegen.\n\nMacht Euch bereit, {name}. Wenn Ahune uns gegenübersteht, wird sein Zorn gewaltig sein.", sourceObjective = "Bringt dieses Magmatotem des Irdenen Rings zum Eisbrocken.", progress = "Dieser Eissplitter lässt das tiefe  Rumpeln und Knacken gewaltiger Gletscherzungen erklingen. Seine Kälte lässt Eure Gedanken erstarren und treibt sie in einen leblosen, endlosen Winter.", completion = "Das Magmatotem zerbirst in drei einzelne Flammen, als Ihr es in die Nähe des Eisbrockens bringt. Der Brocken schimmert - und löst sich anschließend in Luft auf...", sourceObjectiveStatus = "unverified-source-field" }
quests[11696] = { id = 11696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune ist hier!", description = "{name}, Eure Gegenwart ist ein Segen. Ahune befindet sich in den Höhlen und sammelt Kräfte für seinen Angriff. Truppen des Irdenen Rings wurden vorausgeschickt, doch alleine werden sie ihn nicht besiegen können.\n\nErkundet die Höhlen, {name}. Findet unsere Schamanen des Irdenen Rings und meldet Euch bei ihrer Anführerin, Luma Himmelsmutter. Mit vereinten Kräften werden wir Ahune vielleicht besiegen können, bevor es zu spät ist.", sourceObjective = "Findet Luma Himmelsmutter in den Sklavenunterkünften.", completion = "Ahunes Kälte breitet sich in diesen Höhlen aus, {name} - ein Vorgeschmack des eisigen Todes, der uns erwarten würde, sollte er seine volle Stärke erlangen. Erdenmutter sei Dank, dass sie Euch gesandt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ... den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
