quests[11863] = { id = 11863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme der Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11875] = { id = 11875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Vorteil gewinnen", description = "Die Truppen der Offensive der Zerschmetterten Sonne werden jeden Vorteil, den sie sich verschaffen können, nutzen müssen, um Kil'Jaedens Verbündete zurückzuschlagen. Meine Kollegen in Sturmwind haben Öle hergestellt, mit deren Hilfe wir die Klingen und Rüstungen unserer Truppen verstärken können.\n\nDie Hauptzutat - ich spreche von Netherrückständen - gibt es überall in der Scherbenwelt. Man muss nur wissen, wo man suchen muss. Jeder Meister der Kräuterkunde, Kürschnerei und des Bergbaus, der die Zeichen kennt, kann sie sammeln und gleichzeitig seinem Gewerbe nachgehen. Finden kann man die Rückstände nur bei Kräutern, Erzen und Bestien, die allesamt ausschließlich in der Scherbenwelt zu finden sind.", sourceObjective = "Bringt dem Abgesandten Mordin in Shattrath 8 Netherrückstände.", progress = "Habt Ihr Netherrückstände bei Euch?", completion = "Danke für Eure Hilfe, {name}. Jeder Beitrag für die Kriegsvorbereitungen zählt. Unsere Männer werden jeden Vorteil nutzen müssen, den sie sich verschaffen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11877] = { id = 11877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne des Sonnenzorns", description = "Wir verstärken unsere Offensive auf Quel'Danas und haben herausgefunden, dass Kael'thas' Diener einen Gegenangriff planen. Er hofft, dass die Angriffe seiner im Nethersturm stationierten Blutelfen des Sonnenzorns unsere Aufmerksamkeit vom Sonnenbrunnen ablenken und uns dazu bringen werden, Truppen abzuziehen.\n\nWir dürfen das nicht zulassen, {name}. An dieser Front wird jede Klinge benötigt.\n\nReist in den Nethersturm und beschafft Euch ihre Angriffspläne. Jeder der Blutelfen des Sonnenzorns dort oben könnte die Pläne bei sich tragen. Viel Glück, {name}.", sourceObjective = "Lord Torvos in Shattrath möchte, dass Ihr die Angriffspläne des Sonnenzorns beschafft.", progress = "Seid Ihr mit den Plänen zurückgekommen?", completion = "<Lord Torvos nimmt die Pläne entgegen und sieht sie sich an.>\n\nIhr habt der Offensive einen großen Dienst erwiesen, {name}. Wir sollten uns jedoch keine Ruhe gönnen. Unsere Feinde werden in Zukunft sicherlich noch mehr Unheil über uns bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11880] = { id = 11880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Multiphasen-Vermessung", description = "Ich bin mir sicher, dass der 'gnomische Erfinder' ein Spinner ist. Er sprach von irgendwelchen dunklen Verzerrungen, die um Oshu'gun in den Geisterfeldern in Nagrand aufgetaucht sind.\n\nLaut seiner Aussage, soll diese, äh, spektrografische... öh... Multiphasen-Brille es dem Träger erlauben, die Verzerrungen zu sehen und Messungen an ihnen vorzunehmen. Er bestand darauf, dass es für unser Vorhaben am Sonnenbrunnen äußerst wichtig sei, diese Daten zu sammeln. Ich denke zwar, dass er einen Sprung in der Schüssel hat, jedoch wurde ich damit beauftragt, alles zu untersuchen, was vielleicht hilfreich sein könnte. Hättet Ihr etwas dagegen, Messungen durchzuführen?", sourceObjective = "Herold Haronem in Shattrath möchte, dass Ihr die spektrografische Multiphasenbrille benutzt, um 6 Multiphasenmessungen durchzuführen.", progress = "Konntet Ihr die Messungen durchführen? Der Gnom wird mich wieder anbrüllen, wenn ich die kostbaren Daten nicht herbekomme.", completion = "Danke für Eure Hilfe. Ihr wisst gar nicht, wie es ist, wenn man sich mit 'Doktor' Waffelfritte dort drüben auseinandersetzen muss. Wenn er nicht gerade damit beschäftigt ist, meinen Fortschritt zu 'überprüfen', verhökert er gerade eines seiner Geräte - die übrigens alle Erfindungen für militärische Zwecke sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11882] = { id = 11882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel mit dem Feuer", description = "Möchtet Ihr ein paar heiße neue Fertigkeiten erlernen?\n\nOb Ihr jemals meine beeindruckende Fertigkeit erreichen werdet, sei zwar dahingestellt, aber ein oder zwei Kunststückchen werdet Ihr wahrscheinlich aufschnappen können, wenn Ihr <ein aufmerksamer Schüler/eine aufmerksame Schülerin> seid. Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.", sourceObjective = "Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte.", completion = "Grüße. Seid Ihr hier, um zu lernen, was man mit Feuer alles machen kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[11883] = { id = 11883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuertanzen?", description = "Ihr wollt die Feuertanzkunst erlernen?\n\nNun, dann sprecht einfach mit einem Feuertanzmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.", sourceObjective = "Sprecht mit einem Feuertanzmeister in einer der Hauptstädte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11885] = { id = 11885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindesblut", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Karrog der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Benutzt sie bei den Beschwörungskreisen, die es in Skettis gibt. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mitzunehmen.", sourceObjective = "Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück.", completion = "Hervorragend! Hier, nehmt dies. Ich habe dieses Bündel aus den Gegenständen erstellt, die Ihr mir gebracht habt. Damit werdet Ihr Terokk beschwören können.\n\nSeid auf der Hut, {name}. Er ist der mächtigste Arakkoa aller Zeiten. Unterschätzt ihn nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[11886] = { id = 11886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Aktivitäten", description = "Spaß und Frivolität müssen sein, {class}, doch einige von uns haben sich ernsteren Angelegenheiten zu widmen.\n\nZu Beginn des Festes erhielten wir Kunde von unseren Anhängern nahe des Zoramstrands über stark erhöhte Aktivitäten des Schattenhammerkults. Die Macht, die diese Wahnsinnigen verehren, ist tief in der Entstehungsgeschichte dieser Festtage verwurzelt. Dies kann kein Zufall sein. Begebt Euch zum Lager in den Ruinen südlich des Eingangs zur Tiefschwarzen Grotte und findet heraus, ob die Kultisten Informationen liefern können - wendet Gewalt an, falls nötig. Platziert dieses Leuchtfeuer auf dem Boden, sobald Ihr etwas gefunden habt, um einen Führer des Irdenen Rings zu beschwören.", sourceObjective = "Geht zum Lager des Schattenhammers südlich des Eingangs zur Tiefschwarzen Grotte am Zoramstrand im Eschental und sucht nach Briefen des Schattenhammers. Die Kultisten werden sie voraussichtlich bei sich tragen. Benutzt anschließend das totemische Leuchtfeuer, um einen Führer des Irdenen Rings zu beschwören.", progress = "Was habt Ihr entdeckt?", completion = "Das ist Besorgnis erregend, mein Freund. Es deutet daraufhin, dass hinter der bloßen Unruhe der örtlichen Feuer- und Wasserelementare etwas viel Größeres steckt und diesem Etwas auf den Grund gegangen werden muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[11891] = { id = 11891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unschuldige Verkleidung", description = "Dieser Information zufolge scheint es, als hätten die Kultisten ein weiteres Lager nordwestlich der großen Ansammlung auf dem Zoramstrand und als sprächen sie mit... Gästen?\n\nMan könnte Vieles in Erfahrung bringen, würde man das Geschehen verfolgen, {race}. Nehmt diese Kugel - sie wird Euch wie einer der Kriecher aussehen lassen, die am örtlichen Strand vorkommen. Belauscht das Gespräch mit diesen \"Gästen\" der Kultisten im nordwestlich gelegenen Lager und erstattet mir Bericht, sobald Ihr das getan habt.", sourceObjective = "Benutzt die Krabbenkugel und spioniert das neue Lager des Schattenhammers aus. Es befindet sich westlich des Eingangs zur Tiefschwarzen Grotte auf dem Zoramstrand im Eschental. Benutzt anschließend das totemische Leuchtfeuer, um den Führer des Irdenen Rings zu beschwören.", progress = "Konntet Ihr ihren Geheimnissen auf die Spur kommen?", completion = "Sie wollen einen Frostfürsten beschwören? Nein! Sie dürfen das Gleichgewicht nicht stören!", sourceObjectiveStatus = "unverified-source-field" }
quests[11915] = { id = 11915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel mit dem Feuer", description = "Möchtet Ihr ein paar heiße neue Fertigkeiten erlernen?\n\nOb Ihr jemals meine beeindruckende Fertigkeit erreichen werdet, sei zwar dahingestellt, aber ein oder zwei Kunststückchen werdet Ihr wahrscheinlich aufschnappen können, wenn Ihr <ein aufmerksamer Schüler/eine aufmerksame Schülerin> seid. Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte. Sie sollten Euch weiterhelfen können.", sourceObjective = "Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte.", completion = "Grüße. Seid Ihr hier, um zu lernen, was man mit Feuer alles machen kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[11917] = { id = 11917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nKehrt zum Lager am Zoramstrand zurück - dorthin, wo die großen Eisbrocken liegen. Sie nehmen mit ihrer Hilfe Verbindung mit den Elementaren auf - genau so wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mit Hilfe des Eisbrockens auf dem Zoramstrand im Eschental den Leutnant der Frostwelle, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11921] = { id = 11921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln werfen", description = "Seid gegrüßt, Feuerjongleur! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für einen Experten in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Schnell! Es gibt keine Zeit zu verlieren!", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11922] = { id = 11922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ... den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister des Sonnenwendfests.", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11923] = { id = 11923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackeln fangen", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Freudenfeuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier nacheinander und kommt wieder zu mir zurück.\n\nSeid vorsichtig! Die Fackeln sind gefährlich, wenn sie auf dem Boden aufkommen! Und fangt sie alle auf! Wenn eine davon auf den Boden fällt, müsst Ihr zurück zum Freudenfeuer und von vorn anfangen. Viel Glück.", sourceObjective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11924] = { id = 11924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln fangen", description = "Fackeln zu fangen, hält einen auf Zack, daran besteht kein Zweifel. Denkt Ihr, dass Ihr es lange durchhalten werdet?\n\nNa dann lasst uns mal sehen...", sourceObjective = "Fangt nacheinander 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Wie geht es Eurem Arm, {name}? Das war eine glanzvolle Vorstellung dort draußen - wie ein echter Meisterjongleur!", sourceObjectiveStatus = "unverified-source-field" }
quests[11925] = { id = 11925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln fangen", description = "Fackeln zu fangen, hält einen auf Zack, daran besteht kein Zweifel. Denkt Ihr, dass Ihr es lange durchhalten werdet?\n\nNa dann lasst uns mal sehen...", sourceObjective = "Fangt nacheinander 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Wie geht es Eurem Arm, {name}? Das war eine glanzvolle Vorstellung dort draußen - wie ein echter Meisterjongleur!", sourceObjectiveStatus = "unverified-source-field" }
quests[11926] = { id = 11926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln werfen", description = "Seid gegrüßt, Feuerjongleur! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für einen Experten in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11933] = { id = 11933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme der Exodar", description = "Die Flamme, die aus dem Innersten der Exodar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme der Exodar zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Dies scheint mir ein neues Feuer zu sein... Doch Ihr sagt, dass es von der Exodar stammt? Faszinierend! Dass Ihr es ins Innere des Schiffs schaffen konntet... Natürlich werde ich Euch dafür bezahlen. Solltet Ihr etwas Ähnliches finden, dann sucht mich bitte wieder auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[11935] = { id = 11935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Silbermond", description = "Diese Flamme, die aus Silbermond entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Silbermond zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Welch prächtiges Feuer! Ihr habt das hier in Silbermond gefunden, sagt Ihr? Unglaublich! Wer weiß, was wir mit den Flammen aller vier Städte vollbringen könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[11947] = { id = 11947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nIm Schatten des Ethel Rethor im Nordwesten von Desolace befindet sich ein Lager. Dort haben sie Eisbrocken, mit denen sie Verbindung mit den Elementaren aufnehmen - genau so wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mit Hilfe des Eisbrockens am Ethel Rethor in Desolace den Leutnant des Eishagels, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", progress = "Seid Ihr siegreich zurückgekehrt?", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11948] = { id = 11948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nNeptulon hat schon seit längerem eine Operationsbasis auf einer Insel im Westen des Schlingendorntals. Dort hat der Schattenhammerkult Eisbrocken aufgestellt, mit deren Hilfe sie Verbindung mit dem Reich des Gezeitenjägers aufnehmen - genau so wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mit Hilfe des Eisbrockens auf der Insel der Wasserelementare im Westen des Schlingendorntals den Leutnant des Eiswinds, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11952] = { id = 11952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nDer Feuerwachtgrat in der sengenden Schlucht ist eine bekannte Bastion des Schattenhammerkults. Vor kurzem haben sie damit begonnen, mit Hilfe der Eisbrocken in der Höhle Verbindung mit dem Reich des Gezeitenjägers aufnehmen - genau so wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mit Hilfe des Eisbrockens in der Höhle unter dem Feuerwachtgrat im Nordwesten der sengenden Schlucht den Leutnant des Eises, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11953] = { id = 11953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nSilithus ist der Hauptsitz des Schattenhammerkults auf Azeroth. Im Norden haben sie damit begonnen, mit Hilfe neuer Eisbrocken Verbindung mit dem Reich des Gezeitenjägers aufzunehmen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mit Hilfe des Eisbrockens in den Kavernen des Schattenhammers im Norden von Silithus den Leutnant des Gletschers, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11954] = { id = 11954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nUm Ahunes Gelingen zu garantieren, hat der Kult neben dem Dunklen Portal in Draenor ein Basislager errichtet. Sie verwenden Eisbrocken, um die Ankunft des Frostfürsten zu koordinieren. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mit Hilfe des Eisbrockens in der Nähe des Dunklen Portals auf der Höllenfeuerhalbinsel den eisigen Templer, zerstört ihn und kehrt anschließend zu einem der Urahnen des Irdenen Rings zurück. Letztere befinden sich in den Hauptstädten.", progress = "Seid Ihr siegreich zurückgekehrt?", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11955] = { id = 11955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune der Frostfürst", description = "Ich glaube, dass Ihr stark genug seid, um Euch der ultimativen Aufgabe zu stellen, die uns noch bevorsteht.\n\nWir dürfen nicht zulassen, dass das eintrifft, was der Schattenhammerklan und Neptulons Nagaketzer vorhaben. Im Namen Azeroths und allen Lebens auf der Welt: Wir müssen handeln. Uns ist klar, was getan werden muss. Ihr müsst in die Sklavenunterkünfte tief im Inneren des Echsenkessels reisen und Euch dort mit unseren Schamanen treffen. Geht - und macht schnell!", sourceObjective = "Begebt Euch in die Sklavenunterkünfte im Echsenkessel in den Zangarmarschen und sprecht mit Numa Wolkenschwester.", completion = "Den Geistern sei Dank, dass Ihr hier seid! Schnell, wir müssen Ahune beschwören, bevor es zu spät ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[11964] = { id = 11964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauchwerk für die Sommerflämmlinge", description = "Habt Ihr gewusst, dass unsere Feuer des Sonnenwendfestes in jedem Land brennen, in dem auch eine Siedlung der Allianz existiert? Sie befinden sich in den Lagern außerhalb der Städte und werden von Flammenhütern gepflegt. Die Hüter kümmern sich darum, dass die Freudenfeuer hell brennen und die Feierlichkeiten weitergehen.\n\nJeder Flammenhüter hat einen Sommerflämmling bei sich - einen Abgesandten der Geister des Feuers.\n\nMöchtet Ihr einem Sommerflämmling Eure Ehrerbietung erweisen, {name}? Dann nehmt dieses Rauchwerk des Sommers und bringt es einem von ihnen. Besänftigt den kleinen Feuergeist und er könnte sich dafür erkenntlich zeigen.", sourceObjective = "Der Meister der Lehren möchte, dass Ihr einem SommerflämmlingRauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Allianz.", progress = "Feurige Grüße, verehrter {class}. Ihr befindet Euch auf geheiligtem Boden. Willkommen zum Sonnenwendfest.", completion = "Ah, und was haben wir denn hier? Welch angenehmes Aroma! Ich bin mir sicher, dass seine Flamme rein und hell leuchten wird!\n\nNehmt diese Blüte, {name} - nehmt und lasst mich alleine... Ich muss mich um diesen kostbaren Brennstoff kümmern...", sourceObjectiveStatus = "unverified-source-field" }
quests[11966] = { id = 11966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauchwerk für die Festflämmlinge", description = "Habt Ihr gewusst, dass unsere Feuer des Sonnenwendfestes in jedem Land brennen, in dem auch eine Siedlung der Horde existiert? Sie befinden sich in den Lagern außerhalb der Städte und werden von Flammenbewahrern gepflegt. Die Bewahrer kümmern sich darum, dass die Freudenfeuer hell brennen und die Feierlichkeiten weitergehen.\n\nJeder Flammenbewahrer hat einen Festflämmling bei sich - einen Abgesandten der Geister des Feuers.\n\nMöchtet Ihr einem Festflämmling Eure Ehrerbietung erweisen, {name}? Dann nehmt dieses Rauchwerk des Sommers und bringt es einem von ihnen. Besänftigt den kleinen Feuergeist und er könnte sich dafür erkenntlich zeigen.", sourceObjective = "Der Geschichtenerzähler möchte, dass Ihr einem FestflämmlingRauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Horde.", progress = "Feurige Grüße, verehrter {class}. Ihr befindet Euch auf geheiligtem Boden. Willkommen zum Sonnenwendfest.", completion = "Ah, und was haben wir denn hier? Welch angenehmes Aroma! Ich bin mir sicher, dass seine Flamme rein und hell leuchten wird!\n\nNehmt diese Blüte, {name} - nehmt und lasst mich alleine... Ich muss mich um diesen kostbaren Brennstoff kümmern...", sourceObjectiveStatus = "unverified-source-field" }
quests[11970] = { id = 11970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister der Sommerlehre", description = "Unser Fest soll eine Zeit der Freude und des Lachens sein, soviel ist sicher. Es ist jedoch wichtig, dass Ihr den Ursprung dieser Feiertage kennt und versteht. Bildung will ausgesucht sein und gewürdigt werden.\n\nDer Meister der Lehren in den Hauptstädten wird Euch den Weg weisen können. Geht jetzt und lernt.", sourceObjective = "Sprecht mit einem Meister der Lehren in einer der Hauptstädte.", completion = "Liebend gerne werde ich Euch zeigen, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[11971] = { id = 11971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erzähler der Sommergeschichten", description = "Unser Fest soll eine Zeit der Freude und des Lachens sein, soviel ist sicher. Es ist jedoch wichtig, dass Ihr den Ursprung dieser Feiertage kennt und versteht. Bildung will ausgesucht sein und gewürdigt werden.\n\nDer Geschichtenerzähler in den Hauptstädten wird Euch den Weg weisen können. Geht jetzt und lernt.", sourceObjective = "Sprecht mit einem Geschichtenerzähler in einer der Hauptstädte.", completion = "Liebend gerne werde ich Euch zeigen, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[11972] = { id = 11972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter von Ahune", description = "In diesen Splittern pulsiert ein Unheil verkündendes Licht. Halten sie die letzte Essenz des Frostfürsten in ihrem Inneren verborgen?", sourceObjective = "Bringt die Eissplitter zu Luma Himmelsmutter.", progress = "Seid gegrüßt, {name}. Ihr seht besorgt aus, solltet Euch jedoch freuen. Der Frostfürst ist besiegt!", completion = "Ja, diese Splitter enthalten in ihrem Inneren die letzte Essenz des Frostfürsten, die es auf dieser Welt gibt. Wir werden sie beseitigen und Ahune in die niederen Sphären der Kälte verbannen.\n\nDanke Euch, {name}. Euer Name wird für den Rest der Zeit in den Liedern des Irdenen Rings besungen werden. Bitte erweist uns eine Ehre und akzeptiert diese milde Gabe, ein Symbol Eurer Verwandschaft mit Wärme und Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11975] = { id = 11975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nun, wenn ich einmal groß bin...", description = "Vielleicht habe ich Euch das schon gefragt, aber als Ihr so alt wart wie ich, wusstet Ihr dann, dass Ihr eines Tages, wenn Ihr groß seid, <ein/eine:c> {class} sein würdet?\n\nIch weiß nicht, was ich einmal werden will. Vielleicht eine Magierin oder eine Hexenmeisterin oder ein  Blutritter, wie ich davor schon mal gesagt hab? Oder vielleicht... ein Rockstar!! Wie Sig Nicious, der Blutelf, bei den 'Elite Tauren Chieftain'!\n\nHabe gehört, dass wenn die nicht gerade auf Tour sind, dann hängen sie in Silbermond ab! Könntet Ihr mich dorthin bringen? Sie sitzen auf einem Balkon in der Straße der Urahnen herum und warten darauf, dass Leute vorbeikommen.\n\nBitte bringt mich dorthin. Bitte!", sourceObjective = "Geht mit Eurem Waisenkind Salandria zur Straße der Urahnen in Silbermond, um die Elite Tauren Chieftain zu sehen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", progress = "Die Elite Tauren Chieftain sind die besten!", completion = "Habt Ihr das gesehen? Die haben mir zugejubelt!!\n\nNun weiß ich, wie sie sich fühlen, wenn sie auf der Bühne stehen und singen! Ich konnte die Kraft und Energie spüren!\n\nFür mich ist es genauso wie in ihrem Lied!\n\nMy mind is made up, I am going to be a rock star when I grow up! (Mein Entschluss steht fest. Ich werde ein Rockstar sein, wenn ich groß bin!)", sourceObjectiveStatus = "unverified-source-field" }
quests[11976] = { id = 11976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eissplitter", description = "In diesen Splittern pulsiert ein Unheil verkündendes Licht. Halten sie die letzte Essenz des Frostfürsten in ihrem Inneren verborgen?", sourceObjective = "Bringt die Eissplitter zu Luma Himmelsmutter.", sourceObjectiveStatus = "unverified-source-field" }
quests[12012] = { id = 12012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Urahnen benachrichtigen", description = "Hiervon muss der gesamte Irdene Ring erfahren. Ich bin mir nicht sicher, wie es weitergehen soll, doch der Urahne, von dem Ihr überhaupt erst diese Aufgabe bekommen habt, könnte es wissen. Ich bitte Euch, kehrt zum Urahnen zurück und findet heraus, wie es weitergehen soll - wir müssen etwas unternehmen!", sourceObjective = "Reist in eine der Hauptstädte und bringt das totemische Leuchtfeuer zum Urahnen des Irdenen Rings.", progress = "Was bedrückt Euch, mein Kind?", completion = "Das sind in der Tat schlimme Neuigkeiten. Wir müssen alles tun, was in unserer Macht steht, um diesen Krieg zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12020] = { id = 12020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses eine Mal, als ich betrunken war...", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Boxi und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", sourceObjective = "Sprecht mit Boxi Bolzdreher im Braufestlager.", completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, {class}, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, {name}. Weiterhin noch viel Spaß auf dem Braufest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12022] = { id = 12022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut weg das Zeug!", description = "He da! Ihr seht aus, als könntet Ihr gut mit Bier umgehen. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? \n\nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.\n\nEs ist ganz leicht, nehmt einen Freibierkrug und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.", sourceObjective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxi Bolzdreher.", progress = "Hebt einen zu Euch und werft dann einen zu Ihr. A.L.K. hält das aus, dafür habe ich sie ja gebaut.", completion = "Wisst Ihr, was das war? Gnomische Ingenieurskunst von ihrer besten Seite! A.L.K. hat das weggesteckt wie ein Champion!\n\nIch glaube Ihr seid jetzt bereit, wenn die Dunkeleisenzwerge das nächste Mal wieder auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12062] = { id = 12062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beleidigt Coren Düsterbräu", description = "Coren Düsterbräu ist im nächsten Raum und gerade dabei, Dunkeleisenzwerge zu einem weiteren Angriff auf das Braufest aufzustacheln. Macht ihn nieder!\n\nGeht zu ihm hin und provoziert einen Streit. Sagt ihm, dass nicht einmal Säue sein Bier saufen würden.\n\nMacht Euch auf einen Kampf gefasst, wenn Ihr das sagt - das letzte Mal, als jemand über sein Gebräu herzog... warf man ihn Schreckensebern zum Fraß vor.", sourceObjective = "Geht und fangt Streit mit Coren Düsterbräu an.", completion = "Was? Was sagst du da? Du wagst es! Mein Bier kann sich mit dem Spülwasser, das sie auf dem Braufest ausschenken, allemal messen!\n\nDafür wirst du bezahlen, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12133] = { id = 12133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermatsch den Kürbis", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", sourceObjective = "Bring das versengte, heilige Symbol zur kostümierten Waisenmatrone.", progress = "Ja, {name}?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, {name}. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\n Eines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12135] = { id = 12135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Lasset die Feuer kommen!\"", description = "Ihr müsst uns helfen! Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, {name}, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", sourceObjective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht, nachdem der kopflose Reiter diese entzündet hat. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[12139] = { id = 12139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Lasset die Feuer kommen!\"", description = "Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen!\n\nBitte, {name}, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", sourceObjective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der maskierten Matrone, sobald alle Feuer erloschen sind.", completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12155] = { id = 12155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermatsch den Kürbis", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", sourceObjective = "Bring das versengte, heilige Symbol zur maskierten Waisenmatrone.", progress = "Ja, {name}?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, {name}. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\n Eines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12191] = { id = 12191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut weg das Zeug!", description = "Diese lästigen Dunkeleisenzwerge sind wieder da! Wir müssen sichergehen, dass Ihr Euch im Falle eines Falles verteidigen könnt. Noch viel wichtiger ist, wir müssen sichergehen, dass Ihr unser Eigentum verteidigen könnt!\n\nA.L.K. hier wartet auf ein bisschen Action, wie sieht es bei Euch aus? Trinkt aus dem Freibierkrug und werft ihn dann auf A.L.K.! Trefft das Ziel fünfmal und sprecht dann wieder mit mir.", sourceObjective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Bissel Schnellhub.", progress = "Ext den Krug und werft ihn dann auf A.L.K.! Ich denke, die Schläge machen ihr nichts aus. Sonst hätte ich sie ja nicht gestoh... äh... gebaut.", completion = "Wow... A.L.K. ist nicht kaputt gegangen... Hm... Wer hätte das gedacht?\n\nIch meine, hey, Ihr habt es geschafft! Eure Zielfertigkeit ist gut, zumindest gut genug, um bei der Verteidigung des Lagers zu helfen. Ich glaube, Ihr seid nun bereit, den Dunkeleisenzwergen gegenüberzutreten, wenn sie wieder aufkreuzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12192] = { id = 12192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses eine Mal, als ich betrunken war...", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Bissel und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", sourceObjective = "Sprecht mit Bissel Schnellhub im Braufestlager.", completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, {class}, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, {name}. Weiterhin noch viel Spaß auf dem Braufest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12193] = { id = 12193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNa ja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Braufestmarken einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...  \n\nooohhh.... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[12194] = { id = 12194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Braufestmarken einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNa ja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12278] = { id = 12278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[12286] = { id = 12286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diese hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12306] = { id = 12306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Germeinsam ist man stark, {name}. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in der Dunkeldornenlodge im Tal der Geister in Orgrimmar.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in der Dunkeldornenlodge im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet das Braufest!", description = "{name}, unsere Spione haben ein teuflisches Komplott ans Licht gebracht! Die Dunkeleisenzwerge wollen unser geliebtes Braufest dem Erdboden gleichmachen!\n\nCoren Düsterbräu, Oberhaupt einer abtrünnigen Familie von Braumeistern, hat die Zwerge der Schwarzfelstiefen mobilisiert - zudem werden wir auch noch ständig von ihren Maulwurfmaschinen angegriffen.\n\nUnser Spion befindet sich im \"Grimmigen Säufer\", einer Taverne im Inneren des Schwarzfelses. Er wird mehr über Düsterbräus Komplott wissen.", sourceObjective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", completion = "Ihr kommt vom Braufestlager? Was für ein Tag! Das Braufest kann vielleicht noch gerettet werden.\n\n{name}, Coren Düsterbräu muss gestoppt werden! Wir dürfen nicht zulassen, dass er unseren heiligen Feiertag sabotiert. Das Bier muss fließen!", sourceObjectiveStatus = "unverified-source-field" }
